const listCustomers = `-- name: ListCustomers :many
SELECT id, business_id, full_name, phone, email, user_id, created_by, created_at, updated_at FROM customers
WHERE business_id = $1
  AND ($2::text = '' OR lower(full_name) LIKE '%' || lower($2::text) || '%' ESCAPE '\' OR phone LIKE '%' || $2::text || '%' ESCAPE '\')
ORDER BY lower(full_name), id
LIMIT $3
`

type ListCustomersParams struct {
	BusinessID uuid.UUID
	Q          string
	MaxRows    int32
}

// Customers of a business, optionally filtered by name (case-insensitive, contains) or phone
// (contains), by name.
func (q *Queries) ListCustomers(ctx context.Context, arg ListCustomersParams) ([]Customer, error) {
	rows, err := q.db.Query(ctx, listCustomers, arg.BusinessID, arg.Q, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Customer{}
	for rows.Next() {
		var i Customer
		if err := rows.Scan(
			&i.ID,
			&i.BusinessID,
			&i.FullName,
			&i.Phone,
			&i.Email,
			&i.UserID,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockAppointment = `-- name: LockAppointment :one
SELECT id, business_id, professional_id, service_id, customer_user_id, customer_name, customer_phone, start_at, end_at, buffer_minutes, occupied_until, status, service_name, duration_minutes, price_minor, currency, version, created_by, created_at, updated_at, customer_id, cancelled_at, cancel_reason, cancelled_by, customer_reschedules FROM appointments WHERE id = $1 FOR UPDATE
`

// Serializes the changes of one appointment (T6.6).
func (q *Queries) LockAppointment(ctx context.Context, id uuid.UUID) (Appointment, error) {
	row := q.db.QueryRow(ctx, lockAppointment, id)
	var i Appointment
	err := row.Scan(
		&i.ID,
		&i.BusinessID,
		&i.ProfessionalID,
		&i.ServiceID,
		&i.CustomerUserID,
		&i.CustomerName,
		&i.CustomerPhone,
		&i.StartAt,
		&i.EndAt,
		&i.BufferMinutes,
		&i.OccupiedUntil,
		&i.Status,
		&i.ServiceName,
		&i.DurationMinutes,
		&i.PriceMinor,
		&i.Currency,
		&i.Version,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.CustomerID,
		&i.CancelledAt,
		&i.CancelReason,
		&i.CancelledBy,
		&i.CustomerReschedules,
	)
	return i, err
}

