const statsAppointments = `-- name: StatsAppointments :many
SELECT start_at, professional_id, service_id, customer_id, service_name, status, price_minor, duration_minutes
FROM appointments
WHERE business_id = $1 AND start_at >= $2 AND start_at < $3
ORDER BY start_at, id
`

type StatsAppointmentsParams struct {
	BusinessID uuid.UUID
	FromAt     time.Time
	ToAt       time.Time
}

type StatsAppointmentsRow struct {
	StartAt         time.Time
	ProfessionalID  uuid.UUID
	ServiceID       uuid.UUID
	CustomerID      *uuid.UUID
	ServiceName     string
	Status          string
	PriceMinor      int64
	DurationMinutes int16
}

// P-12: the appointments of a business that start in [from_at, to_at), every status.
func (q *Queries) StatsAppointments(ctx context.Context, arg StatsAppointmentsParams) ([]StatsAppointmentsRow, error) {
	rows, err := q.db.Query(ctx, statsAppointments, arg.BusinessID, arg.FromAt, arg.ToAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StatsAppointmentsRow{}
	for rows.Next() {
		var i StatsAppointmentsRow
		if err := rows.Scan(
			&i.StartAt,
			&i.ProfessionalID,
			&i.ServiceID,
			&i.CustomerID,
			&i.ServiceName,
			&i.Status,
			&i.PriceMinor,
			&i.DurationMinutes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateAppointment = `-- name: UpdateAppointment :execrows
UPDATE appointments
SET professional_id = $1, start_at = $2, end_at = $3, occupied_until = $4,
    status = $5, cancelled_at = $6, cancel_reason = $7, cancelled_by = $8,
    customer_reschedules = $9, version = version + 1, updated_at = $10
WHERE id = $11 AND version = $12
`

type UpdateAppointmentParams struct {
	ProfessionalID      uuid.UUID
	StartAt             time.Time
	EndAt               time.Time
	OccupiedUntil       time.Time
	Status              string
	CancelledAt         *time.Time
	CancelReason        *string
	CancelledBy         *string
	CustomerReschedules int16
	UpdatedAt           time.Time
	ID                  uuid.UUID
	Version             int32
}

// Writes a change; the version guard makes a lost update impossible (0 rows = changed meanwhile).
func (q *Queries) UpdateAppointment(ctx context.Context, arg UpdateAppointmentParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateAppointment,
		arg.ProfessionalID,
		arg.StartAt,
		arg.EndAt,
		arg.OccupiedUntil,
		arg.Status,
		arg.CancelledAt,
		arg.CancelReason,
		arg.CancelledBy,
		arg.CustomerReschedules,
		arg.UpdatedAt,
		arg.ID,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

